Opt, Toggles = Library.Options, Library.Toggles
notify = function(text) pcall(function() Library:Notify({ Title = "COMBO_WICK", Description = text, Time = 3 }) end) end
local function section(name, fn)
    local ok, err = xpcall(fn, debug.traceback)
    if not ok then notify(name .. L[" tab failed to load"]); pcall(setclipboard, tostring(err)) end
end
section(L["Suggestions"], function()
    local Tab = Window:AddTab(L["Suggestions"], "message-square")
    local FEEDBACK_URL = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
    local _request = request or (syn and syn.request) or http_request
    local okId, cid = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    local HWID = (okId and type(cid) == "string" and cid ~= "") and cid or tostring(lp.UserId)
    local ERR = {
        empty = "The message is empty.", no_links = "Links are not allowed.", too_long = "Too long (500 max).",
        rate_limited = "You reached the limit. Try again later.", network = "Network error.",
        no_request = "Your executor cannot send requests.", bad_response = "Unexpected server response.",
        unreachable = "Your executor cannot reach the server.",
    }
    local function send(ftype, msg)
        if not _request then return false, "no_request" end
        local ok, res = pcall(function()
            return _request({ Url = FEEDBACK_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode({ type = ftype, message = msg, hwid = HWID, placeId = tostring(game.PlaceId), username = lp.Name, version = CONFIG.VERSION }) })
        end)
        if not ok or type(res) ~= "table" then return false, (type(res) == "string") and "unreachable" or "network" end
        local code = res.StatusCode or res.status_code or res.Status or res.status
        if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. code end
        local dok, data = pcall(function() return HttpService:JSONDecode(res.Body or res.body or "") end)
        if not dok or type(data) ~= "table" then return false, "bad_response" end
        if data.success == true then return true end
        return false, tostring(data.error or "unknown")
    end
    local FG = Tab:AddLeftGroupbox(L["Suggestions / Help"], "message-square")
    FG:AddDropdown("FeedbackType", { Text = L["Type"], Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
    FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = L["Message"], Placeholder = L["500 chars max, no links"] })
    local status = FG:AddLabel("", true)
    local last = 0
    FG:AddButton({ Text = L["Send"], Func = function()
        if tick() - last < 20 then setText(status, string.format(L["Wait %ds"], math.ceil(20 - (tick() - last)))); return end
        local msg = tostring(val("FeedbackMsg", "")):gsub("^%s*(.-)%s*$", "%1")
        if msg == "" then setText(status, ERR.empty); return end
        if #msg > 500 then setText(status, ERR.too_long); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then setText(status, ERR.no_links); return end
        setText(status, L["Sending..."])
        task.spawn(function()
            local ok, err = send(tostring(val("FeedbackType", "Suggestion")):lower(), msg)
            if ok then last = tick(); setText(status, L["Sent. Thank you!"]); pcall(function() Opt.FeedbackMsg:SetValue("") end)
            else setText(status, ERR[err] or (L["Failed: "] .. tostring(err))) end
        end)
    end })
    FG:AddLabel(L["Max 3 messages per hour."], true)
    local HG = Tab:AddRightGroupbox("Help", "life-buoy")
    HG:AddLabel(L["Farm: kills enemies for Kills and stone drops."], true)
    HG:AddLabel(L["Stones: your badge progress and quick collect."], true)
    HG:AddLabel(L["Right Shift opens and closes the menu."], true)
    if CONFIG.DISCORD_INVITE ~= "" then
        HG:AddButton({ Text = L["Copy Discord Invite"], Func = function() pcall(setclipboard, CONFIG.DISCORD_INVITE); notify(L["Discord link copied"]) end })
    end
    ;(function()
        local CB = Tab:AddRightGroupbox(L["Changelog"], "refresh-cw")
        CB:AddLabel("<font color=\"#FFD15C\"><b>Oct 11, 2026</b></font>", true)
        for _, l in ipairs({ L["+ Auto Farm"], L["+ Safe hover farm"], L["+ Aims ahead"], L["+ Drop pickup"], L["+ Weapon picker"], L["+ Stone progress"], L["+ Teleports"], L["+ Enemy ESP"], L["+ Server hop"], L["+ No void death"] }) do CB:AddLabel(l, true) end
    end)()
end)
section(L["Farm"], function()
    local Tab = Window:AddTab(L["Farm"], "swords")
    local FB = Tab:AddLeftGroupbox(L["Auto Farm"], "swords")
    FB:AddToggle("fm_on", { Text = L["Auto Farm"], Default = false, Tooltip = L["Kills enemies for Kills and stone drops"] })
    local fd = FB:AddDependencyBox()
    fd:AddDropdown("fm_mode", { Text = L["Mode"], Values = { "Teleport", "From Range" }, Default = "Teleport", Tooltip = L["Teleport hits every time. From Range never moves you"] })
    fd:AddDropdown("fm_pos", { Text = L["Position"], Values = { "Above", "Behind", "Below" }, Default = "Above", Tooltip = L["Where you hover while farming"] })
    fd:AddSlider("fm_dist", { Text = L["Distance"], Default = 12, Min = 8, Max = 60, Rounding = 0, Suffix = L[" studs"] })
    fd:AddSlider("fm_gap", { Text = L["Attack Delay"], Default = 0.6, Min = 0.3, Max = 3, Rounding = 1, Suffix = "s" })
    fd:AddToggle("fm_equip", { Text = L["Auto Equip Space Stone"], Default = true, Tooltip = L["Grabs the Space Stone weapon if you are not holding it"] })
    fd:SetupDependencies({ { Toggles.fm_on, true } })
    local DB = Tab:AddLeftGroupbox(L["Drops"], "gift")
    DB:AddToggle("dr_note", { Text = L["Notify Drops"], Default = true })
    DB:AddToggle("dr_grab", { Text = L["Auto Pick Up Drops"], Default = true })
    local SB = Tab:AddRightGroupbox(L["Session"], "trending-up")
    UI.status = SB:AddLabel(L["Idle"], false)
    UI.stats = SB:AddLabel("", false)
    UI.stats2 = SB:AddLabel("", false)
    SB:AddButton({ Text = L["Reset Stats"], Func = function() S.kills0, S.frags0, S.hits, S.shots, S.drops = stat("Kills"), stat("Fragments"), 0, 0, 0 end })
end)
section(L["Weapons"], function()
    local Tab = Window:AddTab(L["Weapons"], "zap")
    W.scan()
    local WB = Tab:AddLeftGroupbox(L["Weapon"], "zap")
    WB:AddDropdown("wp_pick", { Text = L["Weapon"], Values = (#W.names > 0) and W.names or { "None" }, Default = 1, Tooltip = L["Only weapons you have unlocked will equip"] })
    WB:AddButton({ Text = L["Equip Weapon"], Func = function()
        task.spawn(function()
            local key = val("wp_pick", "")
            local ok, home = W.pick(key, function() local t = W.current() return t and t or nil end)
            local r = hrp()
            if home and r then task.wait(0.5) end
            notify(ok and (L["Equipped "] .. key) or L["Could not equip that weapon"])
        end)
    end })
    WB:AddToggle("wp_reequip", { Text = L["Re-Equip After Death"], Default = true })
    WB:AddLabel(L["Locked weapons need their badge first."], true)
end)
section(L["Stones"], function()
    local Tab = Window:AddTab(L["Stones"], "egg")
    local PB = Tab:AddLeftGroupbox(L["Progress"], "trending-up")
    UI.progress = PB:AddLabel(L["Checking badges..."], true)
    PB:AddButton({ Text = L["Refresh"], Func = function() task.spawn(function() pcall(PR.refresh) end) end })
    local AB = Tab:AddRightGroupbox(L["Collect"], "hand")
    AB:AddButton({ Text = L["Get Space Stone"], Func = function() task.spawn(PR.space) end })
    AB:AddButton({ Text = L["Go To Next Objective"], Func = function()
        local p, n = PR.nextSpot()
        if p then TP.go(p); notify(L["Next: "] .. tostring(n)) else notify(L["No marked objective left"]) end
    end })
    AB:AddLabel(L["Power, Mind and Soul drop from enemies. Use Auto Farm."], true)
end)
section(L["Teleports"], function()
    local Tab = Window:AddTab(L["Teleports"], "arrow-up")
    local TB = Tab:AddLeftGroupbox(L["Places"], "arrow-up")
    TB:AddDropdown("tp_pick", { Text = L["Place"], Values = TP.names(), Default = 1 })
    TB:AddButton({ Text = "Teleport", Func = function() TP.to(val("tp_pick", "Spawn")) end })
end)
section(L["World"], function()
    local Tab = Window:AddTab(L["World"], "eye")
    local EB = Tab:AddLeftGroupbox(L["Enemy ESP"], "eye")
    EB:AddToggle("es_on", { Text = L["Enemy ESP"], Default = false })
    EB:AddSlider("es_dist", { Text = L["Range"], Default = 400, Min = 100, Max = 2000, Rounding = 0, Suffix = L[" studs"] })
    local WB = Tab:AddRightGroupbox(L["World"], "eye")
    WB:AddToggle("wd_bright", { Text = L["Fullbright"], Default = false, Callback = function(v) pcall(WD.setBright, v) end })
    WB:AddToggle("wd_kill", { Text = L["No Void Death"], Default = true, Callback = function(v) pcall(WD.setKill, v) end })
    local PB = Tab:AddRightGroupbox(L["Player"], "user")
    PB:AddToggle("pl_speed", { Text = L["Walk Speed"], Default = false })
    PB:AddSlider("pl_speedn", { Text = L["Speed"], Default = 32, Min = 16, Max = 100, Rounding = 0 })
    PB:AddToggle("pr_afk", { Text = L["Anti AFK"], Default = true })
    local SV = Tab:AddLeftGroupbox(L["Server"], "server")
    SV:AddButton({ Text = L["Join Low Player Server"], Func = function() task.spawn(HOP.go) end })
    SV:AddLabel(L["Fewer players = more enemies for you."], true)
end)
section(L["Settings"], function()
    local Tab = Window:AddTab(L["Settings"], "settings")
    local Menu = Tab:AddLeftGroupbox(L["Menu"], "menu")
    Menu:AddLabel(L["Menu Key"]):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = L["Menu Key"] })
    Library.ToggleKeybind = Opt.MenuKeybind
    Menu:AddButton({ Text = L["Unload"], Func = function() pcall(_G.__CW_TS_CLEAN) end })
    SaveManager:SetLibrary(Library)
    ThemeManager:SetLibrary(Library)
    SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg" })
    ThemeManager:SetFolder("COMBO_WICK_TS")
    SaveManager:SetFolder("COMBO_WICK_TS")
    ThemeManager:ApplyToTab(Tab)
    pcall(function()
        if not (isfile and isfile("COMBO_WICK_TS/themes/default.txt")) then ThemeManager:ApplyTheme("Tokyo Night") end
    end)
    SaveManager:BuildConfigSection(Tab)
end)
track(lp.Idled:Connect(function()
    if on("pr_afk") then pcall(function() VirtualUser:CaptureController(); VirtualUser:ClickButton2(Vector2.new()) end) end
end))
task.spawn(function()
    task.wait(1)
    pcall(WD.setKill, on("wd_kill"))
    S.kills0, S.frags0 = stat("Kills"), stat("Fragments")
    while RUNNING do
        setText(UI.status, S.task)
        setText(UI.stats, string.format(L["Kills +%d · Fragments +%d"], stat("Kills") - (S.kills0 or 0), stat("Fragments") - (S.frags0 or 0)))
        setText(UI.stats2, string.format(L["Hits %d · Drops %d"], S.hits, S.drops))
        setText(UI.progress, PR.summary())
        task.wait(0.5)
    end
end)
pcall(function() SaveManager:LoadAutoloadConfig() end)
notify(L["Loaded"])

end
